1	import { Logger, VendurePlugin } from '@vendure/core';
2	
3	import { HARDEN_PLUGIN_OPTIONS, loggerCtx } from './constants';
4	import { HideValidationErrorsPlugin } from './middleware/hide-validation-errors-plugin';
5	import { QueryComplexityPlugin } from './middleware/query-complexity-plugin';
6	import { HardenPluginOptions } from './types';
7	
8	/**
9	 * @description
10	 * The HardenPlugin hardens the Shop and Admin GraphQL APIs against attacks and abuse.
11	 *
12	 * - It analyzes the complexity on incoming graphql queries and rejects queries that are too complex and
13	 *   could be used to overload the resources of the server.
14	 * - It disables dev-mode API features such as introspection and the GraphQL playground app.
15	 * - It removes field name suggestions to prevent trial-and-error schema sniffing.
16	 *
17	 * It is a recommended plugin for all production configurations.
18	 *
19	 * ## Installation
20	 *
21	 * `yarn add \@vendure/harden-plugin`
22	 *
23	 * or
24	 *
25	 * `npm install \@vendure/harden-plugin`
26	 *
27	 * Then add the `HardenPlugin`, calling the `.init()` method with {@link HardenPluginOptions}:
28	 *
29	 * @example
30	 * ```ts
31	 * import { HardenPlugin } from '\@vendure/harden-plugin';
32	 *
33	 * const config: VendureConfig = {
34	 *   // Add an instance of the plugin to the plugins array
35	 *   plugins: [
36	 *      HardenPlugin.init({
37	 *        maxQueryComplexity: 650,
38	 *        apiMode: process.env.APP_ENV === 'dev' ? 'dev' : 'prod',
39	 *      }),
40	 *   ],
41	 * };
42	 * ```
43	 *
44	 * ## Setting the max query complexity
45	 *
46	 * The `maxQueryComplexity` option determines how complex a query can be. The complexity of a query relates to how many, and how
47	 * deeply-nested are the fields being selected, and is intended to roughly correspond to the amount of server resources that would
48	 * be required to resolve that query.
49	 *
50	 * The goal of this setting is to prevent attacks in which a malicious actor crafts a very complex query in order to overwhelm your
51	 * server resources. Here's an example of a request which would likely overwhelm a Vendure server:
52	 *
53	 * ```GraphQL
54	 * query EvilQuery {
55	 *   products {
56	 *     items {
57	 *       collections {
58	 *         productVariants {
59	 *           items {
60	 *             product {
61	 *               collections {
62	 *                 productVariants {
63	 *                   items {
64	 *                     product {
65	 *                       variants {
66	 *                         name
67	 *                       }
68	 *                     }
69	 *                   }
70	 *                 }
71	 *               }
72	 *             }
73	 *           }
74	 *         }
75	 *       }
76	 *     }
77	 *   }
78	 * }
79	 * ```
80	 *
81	 * This evil query has a complexity score of 2,443,203 - much greater than the default of 1,000!
82	 *
83	 * The complexity score is calculated by the [graphql-query-complexity library](https://www.npmjs.com/package/graphql-query-complexity),
84	 * and by default uses the {@link defaultVendureComplexityEstimator}, which is tuned specifically to the Vendure Shop API.
85	 *
86	 * :::caution
87	 * Note: By default, if the "take" argument is omitted from a list query (e.g. the `products` or `collections` query), a default factor of 1000 is applied.
88	 * :::
89	 *
90	 * The optimal max complexity score will vary depending on:
91	 *
92	 * - The requirements of your storefront and other clients using the Shop API
93	 * - The resources available to your server
94	 *
95	 * You should aim to set the maximum as low as possible while still being able to service all the requests required.
96	 * This will take some manual tuning.
97	 * While tuning the max, you can turn on the `logComplexityScore` to get a detailed breakdown of the complexity of each query, as well as how
98	 * that total score is derived from its child fields:
99	 *
100	 * @example
101	 * ```ts
102	 * import { HardenPlugin } from '\@vendure/harden-plugin';
103	 *
104	 * const config: VendureConfig = {
105	 *   // A detailed summary is logged at the "debug" level
106	 *   logger: new DefaultLogger({ level: LogLevel.Debug }),
107	 *   plugins: [
108	 *      HardenPlugin.init({
109	 *        maxQueryComplexity: 650,
110	 *        logComplexityScore: true,
111	 *      }),
112	 *   ],
113	 * };
114	 * ```
115	 *
116	 * With logging configured as above, the following query:
117	 *
118	 * ```GraphQL
119	 * query ProductList {
120	 *   products(options: { take: 5 }) {
121	 *     items {
122	 *       id
123	 *       name
124	 *       featuredAsset {
125	 *         preview
126	 *       }
127	 *     }
128	 *   }
129	 * }
130	 * ```
131	 * will log the following breakdown:
132	 *
133	 * ```sh
134	 * debug 16/12/22, 14:12 - [HardenPlugin] Calculating complexity of [ProductList]
135	 * debug 16/12/22, 14:12 - [HardenPlugin] Product.id: ID!     childComplexity: 0, score: 1
136	 * debug 16/12/22, 14:12 - [HardenPlugin] Product.name: String!       childComplexity: 0, score: 1
137	 * debug 16/12/22, 14:12 - [HardenPlugin] Asset.preview: String!      childComplexity: 0, score: 1
138	 * debug 16/12/22, 14:12 - [HardenPlugin] Product.featuredAsset: Asset        childComplexity: 1, score: 2
139	 * debug 16/12/22, 14:12 - [HardenPlugin] ProductList.items: [Product!]!      childComplexity: 4, score: 20
140	 * debug 16/12/22, 14:12 - [HardenPlugin] Query.products: ProductList!        childComplexity: 20, score: 35
141	 * verbose 16/12/22, 14:12 - [HardenPlugin] Query complexity [ProductList]: 35
142	 * ```
143	 *
144	 * @docsCategory core plugins/HardenPlugin
145	 */
146	@VendurePlugin({
147	    providers: [
