import { Mutation, Resolver } from '@nestjs/graphql';
import { ActiveOrderService, Ctx, Logger, RequestContext, UserInputError } from '@vendure/core';
import { CheckoutPaymentIntent, OrdersController } from '@paypal/paypal-server-sdk';

import { loggerCtx } from '../constants';
import { getPayPalClient } from '../paypal-client';
import { PaypalPlugin } from '../paypal.plugin';

interface PaypalOrderResult {
    paypalOrderId: string;
    approvalUrl: string;
}

/**
 * Converts a Vendure money integer (e.g. 1099 for $10.99) to the decimal
 * string format required by PayPal (e.g. "10.99").
 *
 * NOTE: This assumes a 2-decimal-place currency (USD, EUR, GBP, etc.).
 * Zero-decimal currencies such as JPY require a different conversion and
 * should be handled explicitly if added to the supported currency list.
 */
function toPaypalAmount(vendureAmount: number): string {
    return (vendureAmount / 100).toFixed(2);
}

@Resolver()
export class PaypalShopResolver {
    constructor(private activeOrderService: ActiveOrderService) {}

    @Mutation()
    async createPaypalOrder(@Ctx() ctx: RequestContext): Promise<PaypalOrderResult> {
        const order = await this.activeOrderService.getOrderFromContext(ctx);
        if (!order) {
            throw new UserInputError('No active order found. Add items to your cart before creating a PayPal order.');
        }

        const client = getPayPalClient(PaypalPlugin.options);
        const ordersController = new OrdersController(client);

        const amountValue = toPaypalAmount(order.totalWithTax);
        const currencyCode = order.currencyCode as string;

        Logger.verbose(
            `Creating PayPal order for Vendure order ${order.code} — ${currencyCode} ${amountValue}`,
            loggerCtx,
        );

        const response = await ordersController.createOrder({
            body: {
                intent: CheckoutPaymentIntent.Capture,
                purchaseUnits: [
                    {
                        referenceId: order.code,
                        amount: {
                            currencyCode,
                            value: amountValue,
                        },
                    },
                ],
            },
            prefer: 'return=minimal',
        });

        const paypalOrder = response.result;
        if (!paypalOrder?.id) {
            throw new Error('PayPal returned an order without an ID. Please try again.');
        }

        const approveLink = paypalOrder.links?.find(link => link.rel === 'approve');
        if (!approveLink?.href) {
            throw new Error('PayPal did not return an approval URL. Please try again.');
        }

        Logger.verbose(`PayPal order created: ${paypalOrder.id}`, loggerCtx);

        return {
            paypalOrderId: paypalOrder.id,
            approvalUrl: approveLink.href,
        };
    }
}

