            console.log('Using mysql connection');
            return {
                synchronize: true,
                type: 'mariadb',
                host: process.env.DB_HOST || '127.0.0.1',
                port: 3307,
                username: 'vendure',
                password: 'password',
                database: 'vendure-dev',
            };
    }
