    async createRefund(_ctx, _input, amount, _order, payment, _args) {
        const meta = payment.metadata as Record<string, unknown>;
        const captureId = meta?.captureId as string | undefined;

        if (!captureId) {
            return {
                state: 'Failed' as const,
                metadata: {
                    error:
                        'No captureId found on this payment. Only fully captured payments ' +
                        '(CAPTURE intent) can be refunded. Authorized-only payments should be voided instead.',
                },
            };
        }

        // Feature 4 handles full refunds only.
        // A full refund is issued when the requested amount equals the total payment amount.
        // Partial refunds (amount < payment.amount) are implemented in Feature 5.
        if (amount < payment.amount) {
            return {
                state: 'Failed' as const,
                metadata: {
                    error:
                        `Partial refunds are not yet supported (requested ${amount}, payment total ${payment.amount}). ` +
                        'Feature 5 will add partial refund support.',
                },
            };
        }

        Logger.verbose(`Issuing full refund for PayPal capture ${captureId}`, loggerCtx);

        try {
            const client = getPayPalClient(PaypalPlugin.options);
            const paymentsController = new PaymentsController(client);

            // Full refund: omit the body entirely — PayPal refunds the full captured amount.
            const response = await paymentsController.refundCapturedPayment({
                captureId,
                prefer: 'return=representation',
            });

            const refund = response.result;

            if (
                refund.status !== RefundStatus.Completed &&
                refund.status !== RefundStatus.Pending
            ) {
                Logger.warn(
                    `PayPal refund for capture ${captureId} returned status: ${refund.status}`,
                    loggerCtx,
                );
                return {
                    state: 'Failed' as const,
                    transactionId: refund.id,
                    metadata: {
                        captureId,
                        refundId: refund.id,
                        refundStatus: refund.status,
                    },
                };
            }

            const refundState = refund.status === RefundStatus.Completed ? 'Settled' : 'Pending';

            Logger.verbose(
                `PayPal full refund for capture ${captureId} — refundId: ${refund.id}, status: ${refund.status}`,
                loggerCtx,
            );

            return {
                state: refundState as 'Settled' | 'Pending',
                transactionId: refund.id,
                metadata: {
                    captureId,
                    refundId: refund.id,
                    refundStatus: refund.status,
                    refundAmount: refund.amount,
                },
            };
        } catch (err: unknown) {
            const message = extractErrorMessage(err);
            Logger.error(`PayPal full refund failed for capture ${captureId}: ${message}`, loggerCtx);
            return {
                state: 'Failed' as const,
                metadata: { captureId, error: message },
            };
        }
    },
});

